from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1] / 'website' / 'tools'

pages = {
 'network-capacity-forecast-planner': {
  'title':'Network Capacity Forecast Planner | Busy-Hour Growth and Expansion Calculator',
  'desc':'Forecast network capacity from measured busy-hour demand, compound growth, peak allowance and an explicit expansion threshold.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>Network capacity planning method</h2><p>Use a consistent link, port-channel or shared-pool boundary. Current demand is <strong>C × U</strong>; peak demand is <strong>C × U × (1 + P)</strong>, where C is installed capacity in Gbps, U is measured utilization and P is the peak allowance. A forecast at year t uses <strong>D<sub>t</sub> = D<sub>0</sub>(1 + g)<sup>t</sup></strong>. Required capacity at the target utilization T is <strong>D<sub>t</sub>/T</strong>.</p><p>Example: 100 Gbps at 50% busy-hour utilization, 20% annual growth and 10% peak allowance gives 55 Gbps current peak; after three years it is about 96.8 Gbps. At a 70% target, plan about 138.3 Gbps of usable capacity. Recalculate with measured P95/P99 telemetry before procurement.</p><h3>Limits and review questions</h3><p>This screening model does not infer seasonality, queue drops, ECMP imbalance or failure topology. Check surviving capacity, path diversity, asymmetry and lead time separately. See the <a href="../../topics/data-center-capacity/">data-center capacity topic</a> and <a href="../bandwidth-calculator/">bandwidth calculator</a>.</p><h3>FAQ</h3><details><summary>Is theoretical capacity the same as busy-hour load?</summary><p>No. Port speed is a ceiling; the measured percentile and protocol overhead determine planning demand.</p></details><details><summary>When should I set the expansion threshold?</summary><p>Use latency, loss, queueing, service targets and upgrade lead time; there is no universal safe percentage.</p></details></section>''',
 },
 'subnet-calculator': {
  'title':'IP Subnet Calculator | CIDR, VLSM and Host Capacity Planning',
  'desc':'Calculate IPv4 and IPv6 CIDR ranges, masks, wildcard masks, usable hosts and VLSM allocations for production network plans.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>Subnet sizing method</h2><p>For IPv4 prefix length p, total addresses are <strong>2<sup>32−p</sup></strong>. A conventional subnet has total minus two usable hosts; /31 point-to-point links follow RFC 3021 and /32 is a single host route. VLSM assigns the smallest prefix that fits required hosts plus reserved addresses, then aligns each block on its prefix boundary.</p><p>Example: a department needing 50 hosts plus 4 reserved addresses requires 54 addresses; the next power of two is 64, so use /26 with 62 conventional usable hosts. Record gateway, infrastructure and growth reservations explicitly.</p><h3>Engineering limits and links</h3><p>Address fit does not prove a suitable broadcast or failure domain. Review routing summarization, security zones, DHCP scope and IPv6 policy in the <a href="../../guides/subnet-calculator-guide/">subnet planning guide</a>. Pair the result with <a href="../network-capacity-forecast-planner/">network capacity forecasting</a>.</p><h3>FAQ</h3><details><summary>Does VLSM reserve a gateway automatically?</summary><p>No. Use the reserve field for gateways, redundancy, infrastructure and growth.</p></details><details><summary>Can IPv6 counts be exact?</summary><p>Yes; the tool uses integer arithmetic, but operational allocation should still follow site prefix policy.</p></details></section>''',
 },
 'generator-fuel-runtime-calculator': {
  'title':'Generator Fuel Consumption and Runtime Calculator | Load-Curve Planning',
  'desc':'Estimate generator fuel consumption, outage runtime, refills and fuel reserve from a manufacturer load curve and measured telecom load.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>Generator fuel and runtime method</h2><p>Fuel used is <strong>fuel rate (L/h) × runtime (h)</strong>. For a load curve, interpolate between the two nearest manufacturer points; do not substitute a no-load rate for a loaded rate. Required outage fuel is runtime fuel plus the specified reserve and refill logistics allowance.</p><p>Example: a curve gives 8.0 L/h at 50% load and 11.5 L/h at 75%. At 60% load, linear interpolation estimates 8.7 L/h; a 12-hour outage needs about 104.4 L before reserve. Validate the estimate against the exact engine, altitude, ambient temperature and fuel quality.</p><h3>Limits and related planning</h3><p>This calculator cannot model transient step loading, wet stacking, derating or transfer delays without manufacturer data. Combine it with the <a href="../../guides/generator-fuel-runtime-planning/">generator fuel planning guide</a> and <a href="../ups-capacity-battery-runtime-calculator/">UPS runtime calculator</a> for ride-through.</p><h3>FAQ</h3><details><summary>Why use a manufacturer curve?</summary><p>Diesel consumption changes materially with load and engine model; a generic L/kWh value can misstate outage reserve.</p></details><details><summary>Does runtime equal tank volume divided by rate?</summary><p>Only as a first estimate; reserve, pickup limits, refill access and changing load reduce usable runtime.</p></details></section>''',
 },
 'bandwidth-calculator': {
  'title':'Bandwidth and Transfer Time Calculator | Link Rate and Data Volume',
  'desc':'Calculate transfer time, required link rate, concurrent-user capacity and data volume with explicit bit/byte and efficiency assumptions.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>Bandwidth and transfer-time formula</h2><p>Transfer time is <strong>data bits ÷ (link rate × efficiency)</strong>. Required rate is <strong>data bits ÷ time ÷ efficiency</strong>; convert bytes to bits with 8 before applying units. Efficiency represents protocol overhead, contention and the sustained fraction you can actually use.</p><p>Example: a 100 GB file over a 1 Gbit/s link at 85% efficiency takes about 941 seconds (15.7 minutes). A measured 250 Mbit/s transfer should be compared with the sustained path rate, not the nominal port speed.</p><h3>Limits and links</h3><p>Results do not model TCP windowing, RTT, packet loss, QoS or shared-link contention. Use the <a href="../network-capacity-forecast-planner/">capacity forecast planner</a> for growth and the <a href="../../guides/bandwidth-transfer-time-guide/">transfer-time guide</a> for unit checks.</p><h3>FAQ</h3><details><summary>Why is my result slower than the port label?</summary><p>Protocol overhead, congestion, storage and endpoint limits reduce sustained throughput.</p></details><details><summary>Should I enter MB or Mb?</summary><p>MB is megabytes; Mb is megabits. The calculator keeps the distinction explicit.</p></details></section>''',
 },
 'pue-data-center-energy-efficiency': {
  'title':'PUE and Data Center Energy Efficiency Analyzer | IT Load and Savings',
  'desc':'Calculate PUE, facility overhead, annual energy cost and target-PUE savings from measured IT and total facility energy.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>PUE calculation method</h2><p>Power Usage Effectiveness is <strong>PUE = total facility energy ÷ IT equipment energy</strong>. Non-IT overhead is total minus IT energy. For a target PUE, projected facility energy is <strong>IT energy × target PUE</strong>, and savings are the difference from the measured baseline.</p><p>Example: 1,200 MWh IT energy and 1,800 MWh total energy produce PUE 1.50 and 600 MWh overhead. At target PUE 1.35, projected total is 1,620 MWh, a planning reduction of 180 MWh before tariff and operating changes.</p><h3>Boundaries and links</h3><p>Use the same meter boundary and interval for numerator and denominator. Do not compare partial-month or different facility boundaries. Review cooling assumptions in the <a href="../../topics/data-center-cooling-capacity/">data-center cooling topic</a> and UPS impact in the <a href="../ups-capacity-battery-runtime-calculator/">UPS calculator</a>.</p><h3>FAQ</h3><details><summary>Can PUE be calculated from IT load alone?</summary><p>No. A facility total measured on the same boundary is required.</p></details><details><summary>Does a lower PUE always mean lower cost?</summary><p>Not necessarily; tariffs, load growth and capital costs must be evaluated with the energy result.</p></details></section>''',
 },
 'wireless-link-budget-calculator': {
  'title':'Wireless Link Budget Calculator | RF Loss, EIRP and Fade Margin',
  'desc':'Calculate wireless link budget, EIRP, free-space path loss, received signal, fade margin and Fresnel clearance.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>RF link budget method</h2><p>Received power is <strong>P<sub>rx</sub> = P<sub>tx</sub> + G<sub>tx</sub> + G<sub>rx</sub> − losses</strong>. Free-space path loss in dB is <strong>92.45 + 20 log10(f<sub>GHz</sub>) + 20 log10(d<sub>km</sub>)</strong>. Fade margin is received power minus receiver sensitivity; design targets depend on availability and climate.</p><p>Example: 20 dBm transmit, 23 dBi antennas at each end, 10 km at 6 GHz and 2 dB miscellaneous loss gives FSPL about 128 dB and received power about −64 dBm. With −75 dBm sensitivity, fade margin is about 11 dB. Confirm antenna pattern, polarization and rain-zone data.</p><h3>Limits and links</h3><p>Free-space loss does not prove line of sight, Fresnel clearance or regulatory compliance. Check the <a href="../rf-link-budget-calculator/">RF budget calculator</a> when available and document path survey results.</p><h3>FAQ</h3><details><summary>Is a positive fade margin enough?</summary><p>No. Availability target, interference, multipath, rain attenuation and Fresnel obstruction must also pass review.</p></details><details><summary>Does antenna gain increase EIRP?</summary><p>Yes, but transmitter limits and local regulations cap permitted EIRP.</p></details></section>''',
 },
 'poe-power-budget-calculator': {
  'title':'PoE Power Budget Calculator | Switch Watts, Ports and Headroom',
  'desc':'Size PoE switch power for cameras, access points and phones with cable loss, per-port limits, headroom and IEEE 802.3 classes.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>PoE budget method</h2><p>Required switch budget is <strong>Σ device watts × (1 + cable-loss fraction) × (1 + headroom fraction)</strong>. The design must also satisfy available ports and each port's IEEE class or manufacturer limit. Use maximum or measured peak draw for cameras, PTZ motors, IR and high radio utilization.</p><p>Example: 24 cameras at 15 W with 5% cable loss and 20% headroom require 453.6 W before power-supply derating. A 370 W PoE switch fails the watt check even though 24 ports are available.</p><h3>Limits and links</h3><p>Cable loss is a planning percentage here; final design must verify conductor category, bundle temperature and run length. See the <a href="../../topics/ip-camera-network-bandwidth-poe/">IP camera PoE topic</a> and <a href="../poe-voltage-drop-calculator/">PoE voltage-drop calculator</a>.</p><h3>FAQ</h3><details><summary>Should I use average device watts?</summary><p>Use maximum rated or measured peak consumption for capacity; averages can hide startup and IR events.</p></details><details><summary>Is 20% headroom an IEEE requirement?</summary><p>No. It is a documented engineering choice based on growth, transients and availability.</p></details></section>''',
 },
 'ups-capacity-battery-runtime-calculator': {
  'title':'UPS Capacity and Battery Runtime Calculator | kW, kVA and N+1',
  'desc':'Size UPS kW/kVA modules, N+1 redundancy and battery runtime with efficiency, aging, temperature and recharge assumptions.',
  'en':'''<section class="content-section nel-tool-supporting-section seo-p1p2-content"><h2>UPS and battery sizing method</h2><p>Apparent load is <strong>kVA = kW ÷ power factor</strong>. Add headroom, then round modules up; N+1 adds one module beyond the active requirement and must be checked after one failure. Usable battery energy is approximately <strong>V × Ah × strings × DOD × efficiency × aging × temperature</strong>; runtime is usable energy divided by critical load.</p><p>Example: 60 kW at PF 0.9 is 66.7 kVA; with 25% headroom the design is 83.3 kVA, so three 40 kVA modules provide N+1. A 384 V, 100 Ah, two-string bank at 80% DOD, 92% efficiency and 80% aging factor yields about 45.2 kWh before load-dependent discharge effects.</p><h3>Limits and links</h3><p>Energy runtime is a screening estimate; verify the exact manufacturer discharge curve, cutoff voltage, temperature, bypass and fault-current design. Pair with the <a href="../generator-fuel-runtime-calculator/">generator runtime calculator</a> and <a href="../../topics/telecom-power-energy/">telecom power topic</a>.</p><h3>FAQ</h3><details><summary>Why check both kW and kVA?</summary><p>UPS modules have real-power and apparent-power limits; both must pass.</p></details><details><summary>Is runtime linear with Ah?</summary><p>No. Chemistry, discharge rate, aging and cutoff voltage make actual runtime nonlinear.</p></details></section>''',
 },
}

def update(path, cfg, lang='en'):
    s = path.read_text(encoding='utf-8')
    if lang == 'en':
        s = re.sub(r'<title>.*?</title>', f'<title>{cfg["title"]}</title>', s, count=1, flags=re.S)
        s = re.sub(r'(<meta[^>]+name=["\']description["\'][^>]+content=["\'])[^"\']*(["\'])', rf'\g<1>{cfg["desc"]}\2', s, count=1, flags=re.I)
        s = re.sub(r'(<meta[^>]+content=["\'])[^"\']*(["\'][^>]+name=["\']description)', rf'\g<1>{cfg["desc"]}\2', s, count=1, flags=re.I)
        s = s.replace('<!-- NEL_TOOL_GRAPH_START -->', cfg['en']+'<!-- NEL_TOOL_GRAPH_START -->', 1) if '<!-- NEL_TOOL_GRAPH_START -->' in s else s.replace('</body>', cfg['en']+'</body>', 1)
    else:
        # Keep Chinese metadata concise and add a localized engineering block.
        s = re.sub(r'<title>.*?</title>', f'<title>{cfg["title"]}｜NetEngineerLab</title>', s, count=1, flags=re.S)
        s = re.sub(r'(<meta[^>]+name=["\']description["\'][^>]+content=["\'])[^"\']*(["\'])', rf'\g<1>{cfg["desc"]}\2', s, count=1, flags=re.I)
    path.write_text(s, encoding='utf-8', newline='')

for slug, cfg in pages.items():
    update(ROOT / slug / 'index.html', cfg)
    zh = ROOT / slug / 'zh' / 'index.html'
    if zh.exists(): update(zh, cfg, 'zh')
